import {expect} from '@playwright/test';
export async function exerciseAlbumList(page,{lang,prefix,albums,all,saved,screenshot}){
  const text=(zh,en)=>lang==='en'?en:zh;
  await page.locator('.workspace-subnav').getByRole('button',{name:text('影集','Albums'),exact:true}).click();
  const search=page.getByRole('textbox',{name:text('搜索影集名称','Search album names'),exact:true}),sort=page.getByRole('combobox',{name:text('影集列表排序','Album list sort'),exact:true});
  const names=()=>page.locator('.album-card h3').allTextContents();await search.fill(prefix);await sort.selectOption('name');await expect(page.locator('.album-card h3')).toHaveText([prefix+' Hidden',prefix+' Trip 2',prefix+' Trip 10']);
  await page.getByRole('button',{name:text('切换影集升降序','Toggle album sort direction'),exact:true}).click();await expect(page.locator('.album-card h3')).toHaveText([prefix+' Trip 10',prefix+' Trip 2',prefix+' Hidden']);
  await sort.selectOption('count');await expect.poll(async()=>{const rows=await all(),byName=new Map(rows.map(a=>[a.name,a.count]));return(await names()).map(name=>byName.get(name));}).toEqual([1,1,0]);
  // Windows timestamps can tie even for successive requests. The public sort
  // contract uses ID order for ties, rather than the fixture's creation order.
  const newest=[...albums].sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at)||(a.id<b.id?-1:a.id>b.id?1:0));
  await sort.selectOption('created_at');await expect(page.locator('.album-card h3')).toHaveText(newest.map(a=>a.name));
  await sort.selectOption('custom');const initial=await names(),last=page.locator('.album-card').last();await last.getByRole('button',{name:text('上移影集 '+initial[2],'Move album '+initial[2]+' up'),exact:true}).focus();await page.keyboard.press('Enter');await expect(page.locator('.album-card h3')).toHaveText([initial[0],initial[2],initial[1]]);
  const ids=await page.locator('.album-card').evaluateAll(nodes=>nodes.map(node=>node.dataset.albumId));await expect.poll(async()=>(await saved()).order?.filter(id=>ids.includes(id))).toEqual(ids);
  const hidden=albums.find(a=>a.name.endsWith(' Hidden'));await search.fill(prefix+' Trip');const visible=await page.locator('.album-card').evaluateAll(nodes=>nodes.map(node=>node.dataset.albumId));await page.locator('.album-card').last().getByRole('button',{name:text('上移影集 ','Move album ')+((await names())[1])+text('',' up'),exact:true}).click();
  await expect.poll(async()=>(await saved()).order?.filter(id=>visible.includes(id))).toEqual([...visible].reverse());expect((await saved()).order).toContain(hidden.id);
  await search.fill(prefix);const before=await page.locator('.album-card').evaluateAll(nodes=>nodes.map(node=>node.dataset.albumId));const handle=page.locator('.album-card').first().locator('.album-drag-handle'),target=page.locator('.album-card').last();await handle.scrollIntoViewIfNeeded();const from=await handle.boundingBox();await page.mouse.move(from.x+from.width/2,from.y+from.height/2);await page.mouse.down();await page.mouse.move(from.x+from.width/2+12,from.y+from.height/2,{steps:3});await target.scrollIntoViewIfNeeded();const to=await target.boundingBox();await page.mouse.move(to.x+to.width/2,to.y+Math.min(80,to.height/2),{steps:12});await page.mouse.move(to.x+to.width/2+1,to.y+Math.min(80,to.height/2)+1);await page.mouse.up();const reordered=[before[1],before[0],before[2]];await expect.poll(async()=>page.locator('.album-card').evaluateAll(nodes=>nodes.map(node=>node.dataset.albumId))).toEqual(reordered);
  await expect.poll(async()=>(await saved()).order?.filter(id=>reordered.includes(id))).toEqual(reordered);await page.reload();await expect(sort).toHaveValue('custom');await search.fill(prefix);await expect.poll(()=>page.locator('.album-card').evaluateAll(nodes=>nodes.map(node=>node.dataset.albumId))).toEqual(reordered);
  await page.getByRole('button',{name:text('新建影集','New Album'),exact:true}).click();const create=page.getByRole('dialog',{name:text('创建影集','Create Album'),exact:true});await create.getByRole('textbox',{name:text('影集名称','Album Name'),exact:true}).fill(prefix+' New');await create.locator('.modal-footer button.primary').click();await expect(create).not.toBeVisible();
  await expect(sort).toHaveValue('custom');await expect(search).toHaveValue('');await expect(page.locator('.album-card h3').first()).toHaveText(prefix+' New');const created=(await all()).find(a=>a.name===prefix+' New');await expect.poll(async()=>(await saved()).order?.[0]).toBe(created.id);
  const card=page.locator(`[data-album-id="${created.id}"]`);await card.getByRole('button',{name:text('重命名影集 '+created.name,'Rename album '+created.name),exact:true}).click();const rename=page.getByRole('dialog',{name:text('重命名影集','Rename album'),exact:true});const input=rename.getByRole('textbox',{name:text('影集名称','Album Name'),exact:true});await input.fill('   ');await expect(rename.getByRole('button',{name:text('保存名称','Save name'),exact:true})).toBeDisabled();await input.fill(prefix+' Renamed');await input.press('Enter');await expect(rename).not.toBeVisible();await expect(card.locator('h3')).toHaveText(prefix+' Renamed');await expect.poll(async()=>(await saved()).order?.[0]).toBe(created.id);
  await search.fill(prefix);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
  if(lang==='en')expect(await page.locator('.albums-page').innerText()).not.toMatch(/[\u3400-\u9fff]/);
  if(screenshot)await page.screenshot({path:screenshot,fullPage:true});return created;
}
